def parse_minutes(text):
    value = int(text)
    if value < 0:
        raise ValueError('minutes must not be negative')
    return value

def test_parse_minutes_accepts_zero():
    assert parse_minutes('0') == 0

def test_parse_minutes_rejects_negative():
    try:
        parse_minutes('-1')
    except ValueError:
        pass
    else:
        raise AssertionError('negative minutes should be rejected')

# A direct script run must call the tests; pytest discovery is a separate path.
test_parse_minutes_accepts_zero()
test_parse_minutes_rejects_negative()
print('boundary tests passed')

